#!/usr/bin/env bash
# Droit à l'image d'un mineur : les pages (profil du mineur, page du parent, fiche admin).
# Prérequis : apply-docs-circuit-parent.sh. Aucune migration.
# Usage (racine du repo) : bash apply-fix-circuit-parent-pages.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/app/robots.ts" 2>/dev/null | grep -qF "/autorisation-parent"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "### La validation par le parent" "apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-circuit-parent.sh puis apply-docs-circuit-parent.sh"; exit 1; }
MODIFIED=("apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" "apps/web/src/app/robots.ts" "apps/web/src/features/admin/users/components/ImageConsentForms.tsx" "apps/web/src/features/image-consent/OnlineConsentForm.tsx" "e2e/data.mjs" "e2e/prepare.mjs" "packages/backend/src/modules/imageConsent/router.ts")
CREATED=("apps/web/src/app/autorisation-parent/[token]/page.tsx" "apps/web/src/features/admin/users/components/GuardianLinkPanel.tsx" "apps/web/src/features/image-consent/ConsentChoicesFields.tsx" "apps/web/src/features/image-consent/GuardianConsentPage.tsx" "e2e/droit-a-l-image-parent-pages.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/src/app/autorisation-parent/[token]" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "/autorisation-parent" "apps/web/src/app/robots.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/app/autorisation-parent/[token]"
base64 -d > "apps/web/src/app/autorisation-parent/[token]/page.tsx" <<'B64'
